<div class="section-heading"><div><div class="eyebrow">Área clínica</div><h1>Prontuários</h1><p class="text-secondary mb-0">Somente pacientes com vínculo assistencial com seu usuário são exibidos.</p></div></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Paciente</th><th>Contato</th><th>Último atendimento</th><th>Atendimentos</th><th></th></tr></thead><tbody><?php foreach($patients as $p):?><tr><td><strong><?=htmlspecialchars($p['name'],ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars($p['phone']??$p['email']??'—',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($p['last_appointment']??'—',ENT_QUOTES,'UTF-8')?></td><td><?=(int)$p['appointments_count']?></td><td><a class="btn btn-sm btn-outline-primary" href="/clinical/patients/<?=(int)$p['id']?>">Abrir prontuário</a></td></tr><?php endforeach;?><?php if(!$patients):?><tr><td colspan="5"><div class="empty-state">Nenhum paciente com vínculo assistencial disponível.</div></td></tr><?php endif;?></tbody></table></div></div>
